from pathlib import Path
import base64
p=Path('work/scan-1.png')
b64=base64.b64encode(p.read_bytes()).decode()
html=r'''<!doctype html><html><head><meta charset="utf-8"><title>E-Bandobast • 3D deployment planner</title><style>
*{box-sizing:border-box}body{margin:0;background:#0a1221;color:#e5edf8;font:14px system-ui}header{height:76px;border-bottom:1px solid #2a3a50;padding:15px 24px;display:flex;justify-content:space-between;align-items:center}h1{font-size:21px;margin:0 0 4px}small,.muted{color:#9eafc6}main{display:grid;grid-template-columns:310px 1fr;height:calc(100vh - 76px)}aside{padding:20px;overflow:auto;background:#111e30}h2{font-size:12px;color:#8ca3c0;text-transform:uppercase;letter-spacing:1.5px;margin:22px 0 10px}button,select,input{background:#1d3048;color:#eef4fc;border:1px solid #3b506c;border-radius:7px;padding:9px;width:100%;margin:4px 0}button{cursor:pointer}button:hover{background:#2a4666}.primary{background:#087f89}label{font-size:12px;color:#b9c9db}.row{display:flex;gap:7px}.row>*{width:50%}#viewport{position:relative;min-width:0;overflow:hidden}canvas{width:100%;height:100%;display:block;touch-action:none}.badge{border:1px solid #3c516c;border-radius:30px;padding:7px 13px;color:#9ee5d7}#hint{position:absolute;bottom:18px;left:22px;color:#d7e7fa;background:#142338df;padding:10px 16px;border-radius:8px;pointer-events:none}#counts{line-height:1.8}.note{font-size:12px;line-height:1.6;color:#b6c5d8}.check{width:auto}#status{font-size:12px;color:#8de3d7;min-height:20px}@media(max-width:700px){main{grid-template-columns:240px 1fr}header{padding:10px}h1{font-size:16px}}
</style></head><body><header><div><h1>E-Bandobast / 3D deployment planner</h1><small>79th Nirankari Sant Samagam · scan-based planning workspace</small></div><span class="badge">SCHEMATIC DRAFT</span></header><main><aside><div class="note">Source: scanned traffic route plan. Positions are approximate; dimensions, heights and deployment counts require site verification.</div><h2>View</h2><div class="row"><button id="iso">3D view</button><button id="top">Plan view</button></div><label>Rotate <input id="yaw" type="range" min="-180" max="180" value="-12"></label><label>Tilt <input id="tilt" type="range" min="0" max="65" value="38"></label><label>Zoom <input id="zoom" type="range" min="50" max="220" value="90"></label><label><input id="land" type="checkbox" class="check" checked> Raised landmark blocks</label><h2>Place resources</h2><select id="type"><option value="officer">Police officers</option><option value="barricade">Barricade</option><option value="traffic">Traffic post</option><option value="medical">Medical point</option><option value="command">Command post</option><option value="cctv">CCTV</option><option value="water">Drinking water</option><option value="access">Emergency access point</option></select><button class="primary" id="place">Place on plan</button><div class="note">Choose a resource, press Place, then click its location. Click an existing marker to edit it.</div><h2>Selected resource</h2><div id="selected">Select a marker on the model.</div><h2>Deployment totals</h2><div id="counts"></div><h2>Plan files</h2><button id="save">Download deployment JSON</button><button id="load">Open deployment JSON</button><input hidden id="file" type="file" accept=".json"><button id="png">Download current view PNG</button><button id="obj">Download 3D model OBJ</button><button id="reset">Restore example deployment</button><div id="status"></div><p class="note">Saved automatically in this browser when available. JSON is the portable editable plan. OBJ uses arbitrary model units and includes landmark blocks and deployment markers; the scan is embedded in this viewer only.</p></aside><div id="viewport"><canvas id="c"></canvas><div id="hint">Drag to rotate · wheel to zoom · click a marker to edit</div></div></main><script>
const scan=new Image();scan.src='data:image/png;base64,IMAGE';
const c=document.querySelector('#c'),ctx=c.getContext('2d'),$=s=>document.querySelector(s);
const colors={officer:'#49a9ff',barricade:'#ffbd45',traffic:'#a99cff',medical:'#ff6d85',command:'#4ce3c0',cctv:'#d6e0f1',water:'#51d4f6',access:'#8ce894'};
const names={officer:'Police officers',barricade:'Barricades',traffic:'Traffic posts',medical:'Medical points',command:'Command posts',cctv:'CCTV',water:'Water points',access:'Emergency access points'};
const blocks=[['Pandal',.399,.541,.058,.18,28],['Railway station',.519,.067,.087,.029,13],['P1',.201,.633,.044,.05,4],['P2',.28,.532,.06,.05,4],['P3',.58,.12,.082,.08,4],['P4',.597,.564,.077,.05,4]];
const defaults=[{type:'officer',x:.357,y:.748,label:'Gate 1 team',qty:1},{type:'officer',x:.493,y:.695,label:'Gate 2 team',qty:1},{type:'officer',x:.578,y:.677,label:'Gate 3 team',qty:1},{type:'barricade',x:.346,y:.72,label:'Example barricade',qty:1},{type:'traffic',x:.166,y:.491,label:'Example traffic post',qty:1},{type:'medical',x:.459,y:.664,label:'Example medical point',qty:1}];
let items=structuredClone(defaults),selected=-1,placing=false,W,H,scale,ang,tilt,drag;
try{const s=JSON.parse(localStorage.getItem('ebandobast-v1'));if(s)items=s}catch(e){}
function persist(){try{localStorage.setItem('ebandobast-v1',JSON.stringify(items))}catch(e){}}
function setup(){W=c.clientWidth;H=c.clientHeight;c.width=W*devicePixelRatio;c.height=H*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ang=+$('#yaw').value*Math.PI/180;tilt=+$('#tilt').value*Math.PI/180;scale=Math.min(W/1800,H/1354)*+$('#zoom').value/100*.9}
function project(x,y,z=0){let a=(x-.5)*1800,b=(y-.5)*1354;return [W/2+(a*Math.cos(ang)-b*Math.sin(ang))*scale,H/2+(a*Math.sin(ang)+b*Math.cos(ang))*Math.cos(tilt)*scale-z*scale]}
function unproject(x,y){let a=(x-W/2)/scale,b=(y-H/2)/scale/Math.cos(tilt);return [.5+(a*Math.cos(ang)+b*Math.sin(ang))/1800,.5+(-a*Math.sin(ang)+b*Math.cos(ang))/1354]}
function poly(ps,fill,stroke){ctx.beginPath();ps.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function box(x,y,w,h,z,color){let a=project(x,y),b=project(x+w,y),d=project(x,y+h),e=project(x+w,y+h),A=project(x,y,z),B=project(x+w,y,z),D=project(x,y+h,z),E=project(x+w,y+h,z);poly([a,b,B,A],color+'aa','#52677c');poly([b,e,E,B],color+'88','#52677c');poly([e,d,D,E],color+'99','#52677c');poly([A,B,E,D],color,'#c1d2df')}
function draw(){setup();ctx.fillStyle='#0a1423';ctx.fillRect(0,0,W,H);let o=project(0,0);ctx.save();ctx.transform(scale*Math.cos(ang),scale*Math.sin(ang)*Math.cos(tilt),-scale*Math.sin(ang),scale*Math.cos(ang)*Math.cos(tilt),...o);if(scan.complete)ctx.drawImage(scan,0,0,1800,1354);ctx.restore();if($('#land').checked)blocks.forEach(b=>box(...b.slice(1),'#728d9c'));items.map((it,i)=>({...it,i})).sort((a,b)=>project(a.x,a.y)[1]-project(b.x,b.y)[1]).forEach(it=>{let p=project(it.x,it.y),q=project(it.x,it.y,28);ctx.strokeStyle=colors[it.type];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(...p);ctx.lineTo(...q);ctx.stroke();if(it.type==='barricade'){ctx.fillStyle=colors[it.type];ctx.fillRect(q[0]-14,q[1]-7,28,9);ctx.fillStyle='#162234';for(let i=0;i<4;i++)ctx.fillRect(q[0]-11+i*7,q[1]-7,3,9)}else{ctx.fillStyle=colors[it.type];ctx.beginPath();ctx.arc(...q,it.i===selected?10:7,0,7);ctx.fill();ctx.strokeStyle='#fff';ctx.stroke()}ctx.font='bold 11px system-ui';let label=it.label+' · '+it.qty,tw=ctx.measureText(label).width;ctx.fillStyle='#0c1a2ee8';ctx.fillRect(q[0]+12,q[1]-12,tw+12,21);ctx.fillStyle='#fff';ctx.fillText(label,q[0]+18,q[1]+2)});ctx.fillStyle='#a9bbd0';ctx.font='12px system-ui';ctx.fillText('Approximate geometry · example deployment · no verified scale',20,26)}
function refresh(){persist();$('#counts').innerHTML=Object.keys(names).map(k=>`<div><span style="color:${colors[k]}">●</span> ${names[k]} <b style="float:right">${items.filter(i=>i.type===k).reduce((a,b)=>a+b.qty,0)}</b></div>`).join('');let it=items[selected];$('#selected').innerHTML=it?'<label>Label<input id="label"></label><label>Quantity<input id="qty" type="number" min="1" max="10000"></label><button id="move">Move selected on plan</button><button id="delete">Delete selected</button>':'Select a marker on the model.';if(it){$('#label').value=it.label;$('#qty').value=it.qty;$('#label').oninput=e=>{it.label=e.target.value;persist();draw()};$('#qty').onchange=e=>{it.qty=Math.max(1,Math.min(10000,+e.target.value||1));refresh()};$('#delete').onclick=()=>{items.splice(selected,1);selected=-1;refresh()};$('#move').onclick=()=>{placing='move';$('#hint').textContent='Click the new location for the selected resource'}}draw()}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#place').onclick=()=>{placing=true;$('#hint').textContent='Click on the scanned plan to place the resource'};
c.onpointerdown=e=>{drag={x:e.offsetX,y:e.offsetY,yaw:+$('#yaw').value,moved:false};c.setPointerCapture(e.pointerId)};
c.onpointermove=e=>{if(!drag||placing)return;if(Math.hypot(e.offsetX-drag.x,e.offsetY-drag.y)>5){drag.moved=true;$('#yaw').value=drag.yaw+(e.offsetX-drag.x)*.25;draw()}};
c.onpointerup=e=>{if(drag&&!drag.moved){if(placing){let [x,y]=unproject(e.offsetX,e.offsetY);if(x>=0&&x<=1&&y>=0&&y<=1){if(placing==='move'){items[selected].x=x;items[selected].y=y}else{items.push({type:$('#type').value,x,y,label:names[$('#type').value]+' '+(items.length+1),qty:1});selected=items.length-1}placing=false;$('#hint').textContent='Drag to rotate · wheel to zoom · click a marker to edit';refresh()}}else{selected=items.findIndex(it=>{let p=project(it.x,it.y,28);return Math.hypot(p[0]-e.offsetX,p[1]-e.offsetY)<20});refresh()}}drag=null};
c.onwheel=e=>{e.preventDefault();$('#zoom').value=+$('#zoom').value-e.deltaY*.08;draw()};['yaw','tilt','zoom','land'].forEach(id=>$('#'+id).oninput=draw);$('#iso').onclick=()=>{$('#tilt').value=38;$('#yaw').value=-12;draw()};$('#top').onclick=()=>{$('#tilt').value=0;$('#yaw').value=0;draw()};$('#save').onclick=()=>download(new Blob([JSON.stringify({version:1,source:'Adobe Scan 17 Oct 2026.pdf',units:'normalized scan coordinates; no verified scale',items},null,2)],{type:'application/json'}),'e-bandobast-deployment.json');$('#load').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.items)||d.items.length>500)throw Error();items=d.items.map(i=>{if(!colors[i.type]||!Number.isFinite(i.x)||!Number.isFinite(i.y)||i.x<0||i.x>1||i.y<0||i.y>1||!Number.isInteger(i.qty)||i.qty<1||i.qty>10000)throw Error();return {...i,label:String(i.label).slice(0,100)}});selected=-1;refresh();$('#status').textContent='Deployment loaded'}catch(err){$('#status').textContent='Could not open this deployment JSON'}};$('#png').onclick=()=>c.toBlob(b=>download(b,'e-bandobast-view.png'));$('#reset').onclick=()=>{if(confirm('Replace this deployment with the example markers?')){items=structuredClone(defaults);selected=-1;refresh()}};
$('#obj').onclick=()=>{let lines=['# E-Bandobast schematic; arbitrary units; example heights'],n=0;function cube(name,x,y,w,h,z){lines.push('o '+name.replace(/[^a-zA-Z0-9]/g,'_'));[[x,y,0],[x+w,y,0],[x+w,y+h,0],[x,y+h,0],[x,y,z],[x+w,y,z],[x+w,y+h,z],[x,y+h,z]].forEach(v=>lines.push('v '+v.map(v=>v.toFixed(3)).join(' ')));[[1,4,3,2],[1,2,6,5],[2,3,7,6],[3,4,8,7],[4,1,5,8],[5,6,7,8]].forEach(f=>lines.push('f '+f.map(v=>v+n).join(' ')));n+=8}cube('scan_extent',0,0,1800,1354,-2);blocks.forEach(b=>cube(b[0],b[1]*1800,b[2]*1354,b[3]*1800,b[4]*1354,b[5]));items.forEach(i=>cube(i.label,i.x*1800,i.y*1354,i.type==='barricade'?24:8,8,18));download(new Blob([lines.join('\n')],{type:'text/plain'}),'e-bandobast-model.obj')};scan.onload=refresh;window.onresize=draw;refresh();
</script></body></html>'''
Path('outputs/e-bandobast-3d.html').write_text(html.replace('IMAGE',b64),encoding='utf-8')
print('Created self-contained viewer',Path('outputs/e-bandobast-3d.html').stat().st_size)
